CREATE OR REPLACE FUNCTION public.finance_sales_deferred_existing(t uuid,p jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s sales_records;cfg finance_schedule_settings;v jsonb;es jsonb;ls jsonb;uses jsonb:='[]';issued jsonb:='[]';it finance_deferred_items;k text;typ text;amt numeric;remain numeric;sold numeric;used numeric;rev uuid;liability uuid;d date:=(p->>'date')::date;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;PERFORM pg_advisory_xact_lock(hashtextextended('schedule:'||t::text,0));SELECT * INTO s FROM sales_records WHERE tenant_id=t AND id=(p->>'sales_id')::uuid FOR UPDATE;IF s.id IS NULL OR NOT EXISTS(SELECT 1 FROM venues WHERE tenant_id=t AND name=s.venue AND user_has_venue(auth.uid(),id)) THEN RAISE EXCEPTION 'Sales day unavailable';END IF;PERFORM finance_assert_open(t,d);SELECT * INTO cfg FROM finance_schedule_settings WHERE tenant_id=t;v:=p->'values';
IF s.deferred_feed OR EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND status IN('waiting','approved') AND (source_data->>'existing_sales_id'=s.id::text OR source_data->>'sales_id'=s.id::text)) THEN RAISE EXCEPTION 'Existing deferred schedule requires reconciliation first';END IF;
FOREACH k IN ARRAY ARRAY['vouchersSold','depositsTaken','vouchersUsed','depositsUsed'] LOOP amt:=coalesce((v->>k)::numeric,0);IF amt<0 OR amt<>round(amt,2) OR (amt>0 AND NOT (CASE WHEN k LIKE 'vouchers%' THEN coalesce(cfg.voucher_enabled,false) ELSE coalesce(cfg.deposit_enabled,false) END)) THEN RAISE EXCEPTION 'Confirm enabled non-negative cent amounts';END IF;END LOOP;
sold:=coalesce((v->>'vouchersSold')::numeric,0)+coalesce((v->>'depositsTaken')::numeric,0);used:=coalesce((v->>'vouchersUsed')::numeric,0)+coalesce((v->>'depositsUsed')::numeric,0);IF sold+used=0 OR sold>s.subtotal THEN RAISE EXCEPTION 'Confirm deferred amounts included in subtotal';END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('entry',to_jsonb(e),'lines',(SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM journal_lines l WHERE l.entry_id=e.id AND l.tenant_id=t)) ORDER BY e.id),'[]') INTO es FROM journal_entries e WHERE e.tenant_id=t AND e.status='posted' AND ((e.source_type='sales_summary' AND e.source_id=s.date||'__'||s.venue) OR (e.source_type='sales' AND e.source_id=s.id::text));IF jsonb_array_length(es)=0 THEN RAISE EXCEPTION 'Unposted source requires full deferred rebook preparation';END IF;IF (SELECT count(*) FROM sales_records WHERE tenant_id=t AND date=s.date AND venue=s.venue)>1 THEN RAISE EXCEPTION 'Combined sales requires a grouped correction';END IF;
SELECT account_id INTO rev FROM account_mapping_rules WHERE tenant_id=t AND rule_type='sales_revenue' AND match_key=s.venue LIMIT 1;SELECT id INTO liability FROM chart_of_accounts WHERE tenant_id=t AND code='2300' AND account_type='liability' AND is_active LIMIT 1;IF rev IS NULL OR liability IS NULL THEN RAISE EXCEPTION 'Deferred liability and sales mappings required';END IF;
SELECT jsonb_agg(jsonb_build_object('account_id',x->>'account_id','debit',(x->>'credit')::numeric,'credit',(x->>'debit')::numeric,'venue',x->>'venue','memo','Reverse retained source'))||jsonb_agg(jsonb_build_object('account_id',x->>'account_id','debit',(x->>'debit')::numeric,'credit',(x->>'credit')::numeric,'venue',x->>'venue','memo','Rebook retained source')) INTO ls FROM jsonb_array_elements(es) e CROSS JOIN LATERAL jsonb_array_elements(e->'lines') x;
IF sold>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',rev,'debit',sold,'credit',0,'venue',s.venue),jsonb_build_object('account_id',liability,'debit',0,'credit',sold,'venue',s.venue));END IF;IF used>0 THEN ls:=ls||jsonb_build_array(jsonb_build_object('account_id',liability,'debit',used,'credit',0,'venue',s.venue),jsonb_build_object('account_id',rev,'debit',0,'credit',used,'venue',s.venue));END IF;
FOREACH typ IN ARRAY ARRAY['voucher','deposit'] LOOP amt:=CASE WHEN typ='voucher' THEN coalesce((v->>'vouchersSold')::numeric,0) ELSE coalesce((v->>'depositsTaken')::numeric,0) END;IF amt>0 THEN issued:=issued||jsonb_build_array(jsonb_build_object('kind',typ,'amount',amt));END IF;remain:=CASE WHEN typ='voucher' THEN coalesce((v->>'vouchersUsed')::numeric,0) ELSE coalesce((v->>'depositsUsed')::numeric,0) END;FOR it IN SELECT * FROM finance_deferred_items WHERE tenant_id=t AND kind=typ AND venue=s.venue AND status='active' AND issued_date<=s.date::date AND amount>used_amount ORDER BY issued_date,id FOR UPDATE LOOP EXIT WHEN remain<=0;amt:=least(remain,it.amount-it.used_amount);uses:=uses||jsonb_build_array(jsonb_build_object('id',it.id,'amount',amt,'expected_used',it.used_amount));remain:=remain-amt;END LOOP;IF remain>0 THEN RAISE EXCEPTION 'Not enough active deferred balance';END IF;END LOOP;
RETURN finance_schedule_enqueue(t,d,'manual','Deferred correction · '||s.venue,'Retained original reversal and rebook; deferred amounts confirmed','existing-sales-deferred:'||s.id,ls,jsonb_build_object('existing_sales_id',s.id,'fingerprint',md5(to_jsonb(s)::text),'source_entries',es,'values',v,'uses',uses,'issued',issued),s.receipt_file_url,(es->0->'entry'->>'id')::uuid);END $$;
REVOKE ALL ON FUNCTION public.finance_sales_deferred_existing(uuid,jsonb) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.finance_sales_deferred_existing(uuid,jsonb) TO authenticated;
CREATE OR REPLACE FUNCTION public.finance_sales_deferred_check(t uuid,q public.finance_entry_drafts) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l jsonb;i finance_deferred_items;BEGIN
IF NOT finance_schedule_manager(t) THEN RAISE EXCEPTION 'Owner or admin required';END IF;
IF md5(to_jsonb((SELECT s FROM sales_records s WHERE tenant_id=t AND id=(q.source_data->>'existing_sales_id')::uuid))::text) IS DISTINCT FROM q.source_data->>'fingerprint' OR EXISTS(SELECT 1 FROM jsonb_array_elements(q.source_data->'source_entries') e WHERE to_jsonb((SELECT j FROM journal_entries j WHERE tenant_id=t AND id=(e->'entry'->>'id')::uuid)) IS DISTINCT FROM e->'entry' OR (SELECT jsonb_agg(to_jsonb(l) ORDER BY l.id) FROM journal_lines l WHERE tenant_id=t AND entry_id=(e->'entry'->>'id')::uuid) IS DISTINCT FROM e->'lines') THEN RAISE EXCEPTION 'Sales evidence changed';END IF;
FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->'uses') LOOP SELECT * INTO i FROM finance_deferred_items WHERE tenant_id=t AND id=(l->>'id')::uuid FOR UPDATE;IF i.id IS NULL OR i.status<>'active' OR i.used_amount IS DISTINCT FROM (l->>'expected_used')::numeric OR i.amount-i.used_amount<(l->>'amount')::numeric THEN RAISE EXCEPTION 'Deferred balance changed';END IF;END LOOP;END $$;
CREATE OR REPLACE FUNCTION public.finance_sales_deferred_finish(t uuid,q public.finance_entry_drafts) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE l jsonb;s sales_records;BEGIN
IF NOT finance_schedule_manager(t) OR NOT EXISTS(SELECT 1 FROM finance_entry_drafts WHERE tenant_id=t AND id=q.id AND status='approved') THEN RAISE EXCEPTION 'Selected approval required';END IF;SELECT * INTO s FROM sales_records WHERE tenant_id=t AND id=(q.source_data->>'existing_sales_id')::uuid;
FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->'issued') LOOP INSERT INTO finance_deferred_items(tenant_id,kind,reference,venue,issued_date,amount,expires_on,source_sales_id,status) VALUES(t,l->>'kind','Sales correction '||q.id,s.venue,q.entry_date,(l->>'amount')::numeric,CASE WHEN l->>'kind'='voucher' THEN (q.entry_date+make_interval(months=>coalesce((SELECT voucher_expiry_months FROM finance_schedule_settings WHERE tenant_id=t),12)))::date ELSE NULL END,s.id,'active');END LOOP;
FOR l IN SELECT * FROM jsonb_array_elements(q.source_data->'uses') LOOP UPDATE finance_deferred_items SET used_amount=used_amount+(l->>'amount')::numeric,status=CASE WHEN used_amount+(l->>'amount')::numeric=amount THEN 'closed' ELSE 'active' END WHERE tenant_id=t AND id=(l->>'id')::uuid;END LOOP;END $$;
REVOKE ALL ON FUNCTION public.finance_sales_deferred_check(uuid,public.finance_entry_drafts),public.finance_sales_deferred_finish(uuid,public.finance_entry_drafts) FROM PUBLIC,anon,authenticated;
DO $$ DECLARE def text;anchor text;BEGIN SELECT pg_get_functiondef('public.finance_schedule_approve(uuid,uuid,date)'::regprocedure) INTO def;anchor:='PERFORM pg_advisory_xact_lock(hashtextextended(''schedule:''||t::text,0));';IF position(anchor IN def)=0 THEN RAISE EXCEPTION 'Approval lock changed';END IF;def:=replace(def,anchor,anchor||'IF q.source_data ? ''existing_sales_id'' THEN PERFORM finance_sales_deferred_check(t,q);END IF;');anchor:='PERFORM set_config(''finance.keep_reclass_accounts'','''',true);RETURN j;';IF position(anchor IN def)=0 THEN RAISE EXCEPTION 'Approval finish changed';END IF;def:=replace(def,anchor,'IF q.source_data ? ''existing_sales_id'' THEN PERFORM finance_sales_deferred_finish(t,q);END IF;'||anchor);EXECUTE def;END $$;